        <v-card-text class="talent-popup-body"><p class="talent-layout-intro">{{ t('talents.design.layoutHint') }}</p><div class="talent-layout-choices"><button v-for="layout in layouts" :key="layout" type="button" class="talent-layout-choice" :aria-label="t('talents.layouts.' + layout)" @click="create(layout)"><TalentTreePreview :layout="layout" /><div><v-icon :icon="layoutIcons[layout]" size="20" /><strong>{{ t('talents.layouts.' + layout) }}</strong></div><p>{{ t('talents.design.layoutDescriptions.' + layout) }}</p><span class="talent-layout-arrow"><v-icon icon="mdi-arrow-right" size="18" /></span></button></div><section class="talent-import-options"><div><v-icon icon="mdi-file-import-outline" size="24" /><span><strong>{{ t('talents.transfer.importTree') }}</strong><small>{{ t('talents.transfer.completeSettings') }}</small></span></div><v-btn variant="tonal" color="primary" prepend-icon="mdi-file-upload-outline" :disabled="service.state.busy || transfer?.busy" @click="transfer?.openFile()">{{ t('talents.transfer.fileImport') }}</v-btn><v-btn variant="outlined" prepend-icon="mdi-clipboard-text-outline" :disabled="service.state.busy || transfer?.busy" @click="transfer?.openClipboard()">{{ t('talents.transfer.clipboardImport') }}</v-btn></section></v-card-text>
