      <v-card class="talents-ui talent-popup"><v-card-title class="talent-popup-heading"><span class="talent-popup-icon"><v-icon icon="mdi-account-cash-outline" size="30" /></span><div><div class="talent-eyebrow">{{ distributionName }}</div><h2>{{ t('talents.distribute') }}</h2></div><AppCloseButton @click="distribution = null" /></v-card-title><v-divider />
        <v-card-text class="talent-popup-body"><p class="talent-dialog-hint">{{ t('talents.design.distributeHint') }}</p><v-alert v-if="service.state.error" type="error" variant="tonal" class="mb-3">{{ service.state.error }}</v-alert><div class="talent-member-list"><div v-for="member in snapshot.members" :key="member.userId" class="talent-member-row"><span class="talent-avatar" aria-hidden="true">{{ member.name.slice(0, 1).toUpperCase() }}</span><span class="talent-member-name">{{ member.name }}</span><div class="talent-balance-stepper"><v-btn icon="mdi-minus" variant="text" size="small" :aria-label="t('talents.removePoint') + ' ' + member.name" :disabled="service.state.busy || balance(member.player) === 0" @click="setBalance(member.userId, balance(member.player) - 1)" /><v-text-field :model-value="balance(member.player)" type="number" min="0" variant="plain" density="compact" hide-details :aria-label="t('talents.points') + ' ' + member.name" :disabled="service.state.busy" @change="setBalance(member.userId, Number(($event.target as HTMLInputElement).value))" /><v-btn icon="mdi-plus" variant="text" size="small" :aria-label="t('talents.addPoint') + ' ' + member.name" :disabled="service.state.busy" @click="setBalance(member.userId, balance(member.player) + 1)" /></div></div></div></v-card-text><v-card-actions class="talent-popup-footer"><v-spacer /><v-btn color="primary" variant="flat" @click="distribution = null">{{ t('talents.design.done') }}</v-btn></v-card-actions>
      </v-card>
