    <v-dialog :model-value="!!visibilityTree" :fullscreen="smAndDown" max-width="560" scrollable :aria-label="t('talents.visibility')" @update:model-value="!$event && (visibilityTree = null)">
      <v-card class="talents-ui talent-popup"><v-card-title class="talent-popup-heading"><span class="talent-popup-icon"><v-icon icon="mdi-eye-outline" size="30" /></span><div><div class="talent-eyebrow">{{ visibilityName }}</div><h2>{{ t('talents.visibility') }}</h2></div><AppCloseButton @click="visibilityTree = null" /></v-card-title><v-divider /><v-card-text class="talent-popup-body"><p class="talent-dialog-hint">{{ t('talents.visibilityHint') }}</p><div class="talent-member-list"><div v-for="member in snapshot.members" :key="member.userId" class="talent-member-row"><span class="talent-avatar" aria-hidden="true">{{ member.name.slice(0, 1).toUpperCase() }}</span><span class="talent-member-name">{{ member.name }}</span><v-chip v-if="member.player.unlockedTreeIds?.includes(visibilityTree!)" size="x-small" color="primary" variant="tonal">{{ t('talents.progression.earned') }}</v-chip><v-btn v-if="visibilityDefinition?.accessMode === 'restricted'" size="small" :variant="member.player.grantedTreeIds?.includes(visibilityTree!) ? 'tonal' : 'text'" :color="member.player.grantedTreeIds?.includes(visibilityTree!) ? 'primary' : undefined" :aria-label="t(member.player.grantedTreeIds?.includes(visibilityTree!) ? 'talents.progression.revoke' : 'talents.progression.grant') + ' ' + member.name" :disabled="service.state.busy" @click="service.mutate({ op: 'access', treeId: visibilityTree!, targetUserId: member.userId, granted: !member.player.grantedTreeIds?.includes(visibilityTree!) })">{{ t(member.player.grantedTreeIds?.includes(visibilityTree!) ? 'talents.progression.revoke' : 'talents.progression.grant') }}</v-btn><span class="talent-visibility-label" :class="{ 'is-visible': memberHasAccess(member.player, member.userId) }">{{ t(isHidden(member.userId) ? 'talents.design.hidden' : memberHasAccess(member.player, member.userId) ? 'talents.design.visible' : 'talents.progression.locked') }}</span><v-btn :icon="isHidden(member.userId) ? 'mdi-eye-off-outline' : 'mdi-eye-outline'" variant="tonal" size="small" :color="isHidden(member.userId) ? undefined : 'primary'" :aria-label="t(isHidden(member.userId) ? 'talents.showTree' : 'talents.hideTree') + ' ' + member.name" :aria-pressed="!isHidden(member.userId)" :disabled="service.state.busy" @click="service.mutate({ op: 'visibility', treeId: visibilityTree!, targetUserId: member.userId, visible: isHidden(member.userId) })" /></div></div></v-card-text><v-card-actions class="talent-popup-footer"><v-spacer /><v-btn color="primary" variant="flat" @click="visibilityTree = null">{{ t('talents.design.done') }}</v-btn></v-card-actions></v-card>
